import type { StaticCanvas } from 'fabric';
import type { SlideCanvasData } from '@/types';
import { applyImageBackground } from '@/lib/fabricObjects';
import { getMediaUrlById } from '@/lib/mediaStorage';

/**
 * Loads slide JSON onto a canvas and resolves an image background that was
 * set via `meta.backgroundMediaId` without a live-canvas-serialized
 * `backgroundImage` (i.e. slides generated by Songs/Bible/Media). Shared by
 * the interactive editor (EditorWorkspace) and the read-only Present-mode
 * renderer (SlideCanvasRenderer) so the two never render a slide
 * differently from each other.
 */
export async function resolveAndRenderSlide(canvas: StaticCanvas, content: SlideCanvasData): Promise<void> {
  await canvas.loadFromJSON(content);

  const bgMediaId = content.meta?.backgroundMediaId ?? null;
  if (bgMediaId && !canvas.backgroundImage) {
    const url = await getMediaUrlById(bgMediaId);
    if (url) {
      await applyImageBackground(canvas, url);
    }
  }
}
